async forwardTokensAndSample(
  inputIds: Array<number>,
  isPrefill: boolean,
  modelId?: string,
): Promise<number> {
  const [, selectedPipeline] = this.getLLMStates(
    "forwardTokensAndSample",
    modelId,
  );
  return selectedPipeline.forwardTokensAndSample(inputIds, isPrefill);
}

/**
